\begin{definition}
  Given nonempty closed convex cones~${K_1, K_2 \subseteq \R^n}$,
  the \emph{truncated Hausdorff distance between~$K_1$
    and~$K_2$},~${\thaus{K_1}{K_2}}$, is defined as
  \begin{equation}
    \thaus{K_1}{K_2} := \haus{K_1 \cap B_1(0)}{K_2 \cap B_1(0)}.
  \end{equation}
\end{definition}

\begin{definition}\label{DEDA}
  Given a nonempty closed convex and line-free set~${C \subseteq
    \R^n}$, a line-free polyhedron~$P$ is called an
  \emph{${\ed}$-approximation of~$C$} if
  \begin{enumerate}[(i)]
  \item $\exc{\vertices P}{C} \leq \varepsilon$,
  \item $\thaus{\recc{P}}{\recc{C}} \leq \delta$,
  \item $P \supseteq C$.
  \end{enumerate}
\end{definition}

\begin{definition}
  A sequence~$\{C^{\nu}\}_{\nu \in \mathbb{N}}$ of subsets of~$\R^n$ is said
  to \emph{converge to~${C \subseteq \R^n}$ in the sense of
    Painlevé-Kuratowski}, denoted by~${C^{\nu} \rightarrow C}$, if the
  following equalities hold:
  \begin{equation*}
    \begin{aligned}
      C &= \left\lbrace x \in \R^n \middle\vert \begin{matrix} \text{for all open
          neighbourhoods } U \text{ of } x,\\ U \cap C^{\nu}  \neq \emptyset
          \text{ for large enough } \nu\end{matrix} \right\rbrace \\
      &= \left\lbrace x \in \R^n \middle\vert \begin{matrix} \text{for all open
        neighbourhoods } U \text{ of } x,\\ U \cap C^{\nu} \neq \emptyset
        \text{ for infinitely many }\nu\end{matrix} \right\rbrace.
    \end{aligned}
  \end{equation*}
\end{definition}

\begin{theorem}[{see \cite[p.~120]{RW98}}]\label{TPKCHD}
  A sequence~$C^{\nu}$ of nonempty closed and convex sets converges to~$C$
  in the sense of Painlevé-Kuratowski if and only if there exist~$x
  \in \R^n$ and~$r_0 \in \R$, such that for all~$r \geq r_0$ it holds, that
  \begin{equation}
    \haus{C^{\nu} \cap B_r(x)}{C \cap B_r(x)} \rightarrow 0.
  \end{equation}
\end{theorem}

